// Format Handbook - the 50 registered content FORMATS.
//
// GENERATED FROM content_formats.md. Edit that file, then run:
//     dart run tool/sync_formats.dart
// Do not edit this file by hand. The markdown is the source of truth.
//
// A format is the HOW a piece of content is shaped. WHAT it is about lives in the
// idea library and never here. An idea can be executed as `problemFix` or as
// `doThisNotThat` on different days; both are the same idea.
//
// Why its own file rather than brand_system.dart: formats are the most volatile data
// in the app, because testing one five times is the loop this brand actually runs.
// brand_system.dart is imported by ten-plus modules, so a format change would
// otherwise rebuild all of them and couple the two.
//
// Why the handbook must never reference buckets or pillars: if a format's guidance
// says "for a humour bucket", then changing the bucket vocabulary requires touching
// every format. The axes stay separate by construction here.

// ============================================================================
// THE REGISTRY
// ============================================================================

/// Whether a format has been tested enough to draw a conclusion from.
class FormatVerdict {
  /// True only when [testsRun] has reached [minTests].
  final bool allowed;
  final int testsRun;
  final int minTests;

  /// Written to be shown to a person, not logged. It states what is missing and by
  /// how much, because "insufficient data" invites ignoring and "2 of 5, three more
  /// to go" does not.
  final String message;

  const FormatVerdict({
    required this.allowed,
    required this.testsRun,
    required this.minTests,
    required this.message,
  });
}

/// One registered format. Every field maps to a field in `content_formats.md`.
class FormatSpec {
  /// Stable key. Ideas and posted performance reference this, so it is never
  /// renumbered — a renumber silently rewrites history.
  final String id;

  final String name;

  /// One sentence, what this shape is.
  final String definition;

  /// The beat order, written so a prompt can follow it literally. Never prose: the
  /// generator follows beats.
  final List<String> structure;

  /// When to reach for this format, in plain language.
  final String bestFor;

  /// Content types this suits, from [kContentTypeIds].
  final List<String> bestContentTypes;

  /// Goals this actually serves, from [kGoalIds]. This is what makes the
  /// recommendation in T-21 explainable rather than a guess.
  final List<String> bestGoals;

  /// The content type this format is the right answer for when several tie.
  ///
  /// Empty on most formats, and that is the intent. Without it, `problemFix`,
  /// `mistakesList`, `saveThisList` and `doThisNotThat` all scored 3 for
  /// imageSlideshowReel + nonFollowerReach, and the tie broke by declaration order —
  /// which recommended Mistakes List for an idea that is plainly a problem-to-fix.
  /// That is the worst failure mode this file can have: a wrong recommendation with
  /// no visible reason, which reads as a bug and erodes trust in every
  /// recommendation.
  final List<String> defaultFor;

  /// A real Fun Learning With Palak idea executed in this format.
  final String example;

  /// Checkable constraints. "Make it good" is not a rule; "no more than 9 words on
  /// screen" is.
  final List<String> generationRules;

  const FormatSpec({
    required this.id,
    required this.name,
    required this.definition,
    required this.structure,
    required this.bestFor,
    required this.bestContentTypes,
    required this.bestGoals,
    required this.example,
    required this.generationRules,
    this.defaultFor = const [],
  });

  /// Whether this format suits the given content type.
  bool supportsContentType(String contentType) => bestContentTypes.contains(contentType);

  /// Whether this format actually serves the given goal.
  bool servesGoal(String goal) => bestGoals.contains(goal);

  /// The scoring used when proposing a format for an idea.
  ///
  /// Deliberately simple and inspectable rather than clever. The reasoning is shown to
  /// the user in one line, so it has to be explainable in one line, and a heuristic
  /// nobody can audit is a heuristic nobody should trust. Content type is weighted
  /// above goal, because a format that cannot be produced in the chosen content type
  /// is not a weaker recommendation, it is an impossible one.
  int scoreFor({String? contentType, String? goal}) {
    var score = 0;
    if (contentType != null && supportsContentType(contentType)) score += 2;
    if (goal != null && servesGoal(goal)) score += 1;
    return score;
  }

  /// Whether this format declared itself the default for [contentType].
  bool isDefaultFor(String contentType) => defaultFor.contains(contentType);

  // ==========================================================================
  // THE FIVE-TEST RULE, as code rather than as an intention
  // ==========================================================================

  /// The verdict on whether this format has been tested enough to judge.
  ///
  /// "Don't test a format once and call it a failure" is easy to agree with and easy
  /// to forget under deadline. The whole failure mode is judging a format after one
  /// Reel that happened to underperform, retiring it, and never finding out it worked.
  ///
  /// So the rule lives in the handbook, next to the format, and refuses to produce a
  /// verdict before there is a sample. Nothing calls this yet — the Experiments tab
  /// does not exist — but the rule is now something the app enforces rather than
  /// something it intends.
  FormatVerdict verdictAt(int testsRun, {int? minTests}) {
    final required = minTests ?? FormatLibrary.minimumTests;

    if (testsRun <= 0) {
      return const FormatVerdict(
        allowed: false,
        testsRun: 0,
        minTests: 5,
        message: 'Not tested yet. Nothing can be concluded.',
      );
    }
    if (testsRun < required) {
      final left = required - testsRun;
      return FormatVerdict(
        allowed: false,
        testsRun: testsRun,
        minTests: required,
        message: 'Tested $testsRun/$required. '
            '$left more test${left == 1 ? '' : 's'} before any verdict. '
            'One Reel is not evidence.',
      );
    }
    return FormatVerdict(
      allowed: true,
      testsRun: testsRun,
      minTests: required,
      message: 'Tested $testsRun/$required. Enough to draw a conclusion.',
    );
  }

  /// The verdict using the standard minimum of [FormatLibrary.minimumTests].
  FormatVerdict verdict(int testsRun) => verdictAt(testsRun);

  /// The one-line reasoning shown alongside a recommendation.
  String reason({String? contentType, String? goal}) {
    final parts = <String>[];
    if (contentType != null) {
      parts.add(supportsContentType(contentType)
          ? 'works as $contentType'
          : 'does not suit $contentType');
    }
    if (goal != null) {
      parts.add(servesGoal(goal) ? 'serves $goal' : 'weak for $goal');
    }
    return parts.isEmpty ? bestFor : parts.join(', ');
  }

  /// The block injected into a generation prompt for this format.
  ///
  /// Beats and rules, not the example. The example is one author's execution of the
  /// format and including it in every prompt invites the generator to re-tell it
  /// rather than follow the shape.
  String toPromptBlock() => '''
FORMAT: $name ($id)
Definition: $definition

Structure, in order:
${structure.map((b) => '  $b').join('\n')}

Generation rules:
${generationRules.map((r) => '  - $r').join('\n')}

Best for: $bestFor''';
}

